295:   @Override
296:   public <T, O> T parse(TypedData body, Parse<T, O> parse) throws Exception {
297:     Function<Parser<?>, T> parserPredicate;
298:     List<Parser<?>> parsers = Lists.newArrayList();
299:     if (parse.getOpts().isPresent()) {
300:       parserPredicate = parser -> {
301:         if (parser.getOptsType().isInstance(parse.getOpts().get())) {
302:           parsers.add(parser);
303:           Parser<O> cast = Types.cast(parser);
304:           return cast.parse(DefaultContext.this, body, parse);
305:         }
306:         return null;
307:       };
308:     } else {
309:       parserPredicate = parser -> {
310:         parsers.add(parser);
311:         Parser<O> cast = Types.cast(parser);
312:         return cast.parse(DefaultContext.this, body, parse);
313:       };
314:     }
315: 
316:     return joinedRegistry
317:       .first(PARSER_TYPE_TOKEN, parserPredicate)
318:       .orElseThrow(() -> new NoSuchParserException(parse.getType(), parse.getOpts().orElse(null), body.getContentType().getType(), parsers));
319:   }
