298:     List<Parser<?>> parsers = Lists.newArrayList();
299:     if (parse.getOpts().isPresent()) {
300:       parserPredicate = parser -> {
301:         if (parser.getOptsType().isInstance(parse.getOpts().get())) {
302:           parsers.add(parser);
303:           Parser<O> cast = Types.cast(parser);
304:           return cast.parse(DefaultContext.this, body, parse);
305:         }
306:         return null;
307:       };
308:     } else {
