120:     private ChainIndex(Handler[] handlers, Registry registry, boolean first) {
121:       this.chainHandlers = handlers;
122:       this.currentRegistry = registry;
123:       this.isRootChain = first;
124:     }
125: 
126:     public Handler next() {
127:       return chainHandlers[currentIndex++];
128:     }
129: 
130:     @Override
131:     public boolean hasNext() {
132:       return currentIndex < chainHandlers.length;
