139:   public static void start(EventLoop eventLoop, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
140:     PathBinding initialPathBinding = new RootPathBinding(requestConstants.request.getPath());
141:     Registry pathBindingRegistry = Registry.single(PathBinding.class, initialPathBinding);
142:     ChainIndex index = new ChainIndex(handlers, registry.join(pathBindingRegistry), true);
143:     requestConstants.chainIndexStack.push(index);
144: 
145:     DefaultContext context = new DefaultContext(requestConstants);
146:     requestConstants.context = context;
147: 
148:     requestConstants.applicationConstants.execController.fork()
149:       .onError(throwable -> requestConstants.context.error(throwable instanceof HandlerException ? throwable.getCause() : throwable))
150:       .onComplete(onComplete)
151:       .register(s -> s
152:           .add(Context.class, context)
153:           .add(Request.class, requestConstants.request)
154:           .add(Response.class, requestConstants.response)
155:           .addLazy(RequestId.class, () -> registry.get(RequestId.Generator.class).generate(requestConstants.request))
