217:         if (handler.getClass().equals(ChainHandler.class)) {
218:           requestConstants.chainIndexStack.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getCurrentRegistry(), false));
219:           currentChainIndex = requestConstants.chainIndexStack.peek();
