221:         }
222:       } else if (currentChainIndex.isRootChain) {
223:         handler = requestConstants.applicationConstants.end;
224:       } else {
225:         requestConstants.chainIndexStack.pop();
226:         currentChainIndex = requestConstants.chainIndexStack.peek();
227:       }
