377:   public void error(Throwable throwable) {
378:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
379:     throwable = unpackThrowable(throwable);
380: 
381:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
382:     if (throwableHolder == null) {
383:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
384: 
385:       try {
386:         serverErrorHandler.error(this, throwable);
387:       } catch (Throwable errorHandlerThrowable) {
388:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
389:       }
390:     } else {
391:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
392:     }
393:   }
