17: package ratpack.path;
18: 
19: import ratpack.path.internal.DefaultPathBinderBuilder;
20: 
21: import java.util.regex.Matcher;
22: import java.util.regex.Pattern;
23: 
24: public abstract class PathBinders {
25: 
26:   private static final Pattern PLACEHOLDER = Pattern.compile("((?:^|/):(\\w+)\\??:([^/])+)|((?:^|/)::([^/])+)|((?:^|/):(\\w+)\\??)");
27: 
28:   private PathBinders() {
29: 
30:   }
31: 
32:   public static PathBinder parse(String path, boolean exact) {
33:     PathBinderBuilder pathBinderBuilder = new DefaultPathBinderBuilder();
34: 
35:     Matcher matchResult = PLACEHOLDER.matcher(path);
36: 
37:     int lastIndex = 0;
38: 
39:     if (matchResult.find()) {
40:       do {
41:         int thisIndex = matchResult.start();
42:         if (thisIndex != lastIndex) {
43:           pathBinderBuilder.literal(path.substring(lastIndex, thisIndex));
44:         }
45:         lastIndex = matchResult.end();
46:         String component = matchResult.group(0);
47:         boolean found = false;
48:         for (TokenType type : TokenType.values()) {
49:           if (type.match(component, pathBinderBuilder)) {
50:             found = true;
51:             break;
52:           }
53:         }
54:         if (!found) {
55:           throw new IllegalArgumentException(String.format("Cannot match path %s (%s)", path, component));
56:         }
57:       } while (matchResult.find());
58:       if (lastIndex < path.length()) {
59:         pathBinderBuilder.literal(path.substring(lastIndex));
60:       }
61:     } else {
62:       pathBinderBuilder.literal(path);
63:     }
64:     return pathBinderBuilder.build(exact);
65:   }
66: 
67:   public static PathBinderBuilder builder() {
68:     return new DefaultPathBinderBuilder();
69:   }
70: 
71:   private enum TokenType implements TokenProcessor {
72:     OPTIONAL_TOKEN_WITH_PATTERN("/?:(\\w*)\\?:(.+)") {
73:       public void process(Matcher matcher, PathBinderBuilder builder) {
74:         builder.optionalTokenWithPattern(matcher.group(1), matcher.group(2));
75:       }
76:     },
77:     LITERAL_WITH_PATTERN("/?::(.+)") {
78:       public void process(Matcher matcher, PathBinderBuilder builder) {
79:         builder.literalPattern(matcher.group(1));
80:       }
81:     },
82:     TOKEN_WITH_PATTERN("/?:(\\w*):(.+)") {
83:       public void process(Matcher matcher, PathBinderBuilder builder) {
84:         builder.tokenWithPattern(matcher.group(1), matcher.group(2));
85:       }
86:     },
87:     TOKEN("/?:(\\w*)") {
88:       public void process(Matcher matcher, PathBinderBuilder builder) {
89:         builder.token(matcher.group(1));
90:       }
91:     },
92:     OPTIONAL_TOKEN("/?:(\\w*)\\?") {
93:       public void process(Matcher matcher, PathBinderBuilder builder) {
94:         builder.optionalToken(matcher.group(1));
95:       }
96:     };
97: 
98:     boolean match(String component, PathBinderBuilder builder) {
99:       Matcher matcher = pattern.matcher(component);
100:       if (matcher.matches()) {
101:         process(matcher, builder);
102:         return true;
103:       }
104:       return false;
105:     }
106: 
107:     private Pattern pattern;
108: 
109:     TokenType(String pattern) {
110:       this.pattern = Pattern.compile(pattern);
111:     }
112:   }
113: 
114:   private interface TokenProcessor {
115:     void process(Matcher matcher, PathBinderBuilder builder);
116:   }
117: }
