39:   @Override
40:   public <T> Observable<T> observe(final Callable<T> callable) {
41:     return Observable.create(new OnSubscribe<>(callable, new Action2<T, Subscriber<? super T>>() {
42:       @Override
43:       public void call(T thing, Subscriber<? super T> subscriber) {
44:         subscriber.onNext(thing);
45:       }
46:     }));
47:   }
48: 
49:   @Override
50:   public <I extends Iterable<T>, T> Observable<T> observeEach(final Callable<I> callable) {
51:     return Observable.create(new OnSubscribe<>(callable, new Action2<I, Subscriber<? super T>>() {
52:       @Override
53:       public void call(I things, Subscriber<? super T> subscriber) {
54:         for (T thing : things) {
55:           subscriber.onNext(thing);
56:         }
57:       }
58:     }));
59:   }
