51:     return Observable.create(new OnSubscribe<>(promise, new Action2<I, Subscriber<? super T>>() {
52:       @Override
53:       public void call(I things, Subscriber<? super T> subscriber) {
54:         for (T thing : things) {
55:           subscriber.onNext(thing);
56:         }
57:       }
58:     }));
59:   }
60: 
61:   private class OnSubscribe<T, S> implements Observable.OnSubscribe<S> {
62:     private final Callable<T> promise;
63:     private final Action2<T, Subscriber<? super S>> emitter;
64: 
65:     public OnSubscribe(Callable<T> callable, Action2<T, Subscriber<? super S>> emitter) {
66:       this.promise = callable;
67:       this.emitter = emitter;
68:     }
69: 
70:     @Override
71:     public void call(final Subscriber<? super S> subscriber) {
72:       try {
73:         background.exec(promise)
74:           .onError(new Action<Throwable>() {
75:             @Override
76:             public void execute(Throwable throwable) throws Exception {
77:               subscriber.onError(throwable);
78:             }
79:           })
80:           .then(new Action<T>() {
81:             @Override
82:             public void execute(T thing) throws Exception {
83:               emitter.call(thing, subscriber);
84:               subscriber.onCompleted();
85:             }
86:           });
87:       } catch (Exception e) {
88:         throw ExceptionUtils.uncheck(e);
89:       }
90:     }
91:   }
