33: public class CachingPromise<T> implements Promise<T> {
34: 
35:   private final Action<? super Fulfiller<T>> fulfillment;
36:   private final Supplier<ExecutionBacking> executionSupplier;
37:   private final Action<? super Throwable> errorHandler;
