40: 
41:   private final ConcurrentLinkedQueue<Fulfiller<T>> waiting = new ConcurrentLinkedQueue<>();
42:   private final AtomicBoolean draining = new AtomicBoolean();
43:   private final AtomicReference<Result<T>> result = new AtomicReference<>();
44: 
45:   public CachingPromise(Action<? super Fulfiller<T>> action, Supplier<ExecutionBacking> executionSupplier, Action<? super Throwable> errorHandler) {
46:     this.fulfillment = action;
47:     this.executionSupplier = executionSupplier;
48:     this.errorHandler = errorHandler;
49:   }
50: 
51:   @Override
