53:     return new DefaultSuccessPromise<>(executionSupplier, new Fulfillment(), errorHandler);
54:   }
55: 
56:   @Override
57:   public void then(Action<? super T> then) {
58:     newPromise().then(then);
59:   }
60: 
61:   private void tryDrain() {
62:     if (draining.compareAndSet(false, true)) {
63:       try {
64:         Result<T> result = this.result.get();
65: 
66:         Fulfiller<T> poll = waiting.poll();
67:         while (poll != null) {
68:           fulfill(result, poll);
69:           poll = waiting.poll();
70:         }
71:       } finally {
72:         draining.set(false);
73:       }
74:     }
75:     if (!waiting.isEmpty()) {
76:       tryDrain();
77:     }
78:   }
79: 
80:   private DefaultSuccessPromise<T> newPromise() {
81:     return new DefaultSuccessPromise<>(executionSupplier, new Fulfillment(), errorHandler);
82:   }
