115:     @Override
116:     public void execute(Fulfiller<T> fulfiller) throws Exception {
117:       if (fired.compareAndSet(false, true)) {
118:         try {
119:           fulfillment.execute(new Fulfiller<T>() {
120:             @Override
121:             public void error(Throwable throwable) {
122:               result.set(DefaultResult.<T>failure(throwable));
123:               tryDrain();
124:             }
125: 
126:             @Override
127:             public void success(T value) {
128:               result.set(DefaultResult.success(value));
129:               tryDrain();
130:             }
131:           });
132:         } catch (Throwable throwable) {
133:           result.set(DefaultResult.<T>failure(throwable));
134:           tryDrain();
135:         }
136:       }
137: 
138:       Result<T> resultValue = result.get();
139:       if (resultValue == null) {
140:         waiting.add(fulfiller);
141:         if (result.get() != null) {
142:           tryDrain();
143:         }
144:       } else {
145:         fulfill(resultValue, fulfiller);
146:       }
147:     }
148:   }
