486:    * @param path the relative path to match exactly on
487:    * @param handler the handler to delegate to
488:    * @return this
489:    * @see Chain#post(String, Handler)
490:    * @see Chain#get(String, Handler)
491:    * @see Chain#put(String, Handler)
492:    * @see Chain#patch(String, Handler)
493:    * @see Chain#delete(String, Handler)
494:    */
495:   default Chain path(String path, Handler handler) {
496:     return all(Handlers.path(path, handler));
497:   }
