357:     Date ifModifiedSinceHeader = requestConstants.request.getHeaders().getDate(IF_MODIFIED_SINCE);
358:     long lastModifiedSecs = date.getTime() / 1000;
359: 
360:     if (ifModifiedSinceHeader != null) {
361:       long time = ifModifiedSinceHeader.getTime();
362:       long ifModifiedSinceSecs = time / 1000;
363: 
364:       if (lastModifiedSecs == ifModifiedSinceSecs) {
365:         requestConstants.response.status(NOT_MODIFIED.code()).send();
366:         return;
367:       }
368:     }
369: 
