603:     private Config config;
604: 
605:     @Inject
606:     public HandlerDecoratorProvider(Config config) {
607:       this.config = config;
608:     }
609: 
610:     @Override
611:     public HandlerDecorator get() {
612:       return HandlerDecorator.prepend(new RequestTimingHandler(config));
613:     }
614:   }
