168:     Properties fileProperties = new Properties(defaultProperties);
169:     if (configFile != null && configFile.exists()) {
170:       try (InputStream inputStream = new FileInputStream(configFile)) {
171:         fileProperties.load(inputStream);
172:       } catch (Exception e) {
173:         throw new LaunchException("Could not read config file '" + configFile + "'", e);
174:       }
175:     }
176: 
177:     fileProperties.putAll(overrideProperties);
178: 
179:     return createWithBaseDir(classLoader, baseDir, fileProperties);
180:   }
