182:   /**
183:    * Constructs a launch config, based on the given properties.
184:    * <p>
185:    * See {@link Property} for details on the valid properties.
186:    *
187:    * @param classLoader The classloader used to load the {@link Property#HANDLER_FACTORY} class
188:    * @param baseDir The {@link org.ratpackframework.launch.LaunchConfig#getBaseDir()} value
189:    * @param properties The values to use to construct the launch config
190:    * @return A launch config
191:    */
192:   public static LaunchConfig createWithBaseDir(ClassLoader classLoader, File baseDir, Properties properties) {
193:     try {
194:       String handlerFactoryClassName = properties.getProperty(Property.HANDLER_FACTORY);
195:       if (handlerFactoryClassName == null) {
196:         throw new LaunchException("No handler factory class specified (config property: " + Property.HANDLER_FACTORY + ")");
197:       }
198: 
199:       Class<?> untypedClass = classLoader.loadClass(handlerFactoryClassName);
200:       if (!HandlerFactory.class.isAssignableFrom(untypedClass)) {
201:         throw new LaunchException("Given handler factory class '" + handlerFactoryClassName + "' does not implement '" + HandlerFactory.class.getName());
202:       }
203: 
204:       @SuppressWarnings("unchecked") Class<HandlerFactory> handlerFactoryClass = (Class<HandlerFactory>) untypedClass;
205: 
206:       int port = Integer.valueOf(properties.getProperty(Property.PORT, new Integer(LaunchConfig.DEFAULT_PORT).toString()));
207: 
208:       InetAddress address = null;
209:       String addressString = properties.getProperty(Property.ADDRESS);
210: 
211:       if (addressString != null) {
212:         try {
213:           address = InetAddress.getByName(addressString);
214:         } catch (UnknownHostException e) {
215:           throw new IllegalStateException("Failed to resolve requested bind address: " + addressString, e);
216:         }
217:       }
218: 
219:       URI uri = null;
220:       String uriString = properties.getProperty(Property.URI);
221: 
222:       if (uriString != null) {
223:         try {
224:           uri = new URI(uriString);
225:         } catch (URISyntaxException ex) {
226:           throw new IllegalStateException("Failed to create URI from: " + uriString, ex);
227:         }
228:       }
229: 
230:       boolean reloadable = Boolean.parseBoolean(properties.getProperty(Property.RELOADABLE, "false"));
231:       int mainThreads = Integer.valueOf(properties.getProperty(Property.MAIN_THREADS, "0"));
232: 
233:       String indexFilesValue = properties.getProperty(Property.INDEX_FILES, "");
234:       ImmutableList.Builder<String> trimmed = ImmutableList.builder();
235:       for (String value : indexFilesValue.split(",")) {
236:         value = value.trim();
237:         if (!value.isEmpty()) {
238:           trimmed.add(value);
239:         }
240:       }
241:       List<String> indexFiles = trimmed.build();
242: 
243:       Map<String, String> otherProperties = new HashMap<>();
244:       extractProperties("other.", properties, otherProperties);
245: 
246:       HandlerFactory handlerFactory;
247:       try {
248:         handlerFactory = handlerFactoryClass.newInstance();
249:       } catch (Exception e) {
250:         throw new LaunchException("Could not instantiate handler factory: " + handlerFactoryClass.getName(), e);
251:       }
252: 
253:       return LaunchConfigBuilder.baseDir(baseDir)
254:         .port(port)
255:         .address(address)
256:         .publicAddress(uri)
257:         .reloadable(reloadable)
258:         .mainThreads(mainThreads)
259:         .indexFiles(indexFiles)
260:         .other(otherProperties)
261:         .build(handlerFactory);
262: 
263:     } catch (Exception e) {
264:       if (e instanceof LaunchException) {
265:         throw (LaunchException) e;
266:       } else {
267:         throw new LaunchException("Failed to create launch config with properties: " + properties.toString(), e);
268:       }
269:     }
270:   }
