32: /**
33:  * A helper for creating a base dir programmatically, typically at test time.
34:  * <p>
35:  * This is typically used in conjunction with {@link EmbeddedApp}, when the app requires a base dir.
36:  * It is however also useful for any kind of testing where a “filesystem” is needed just for the test.
37:  * <p>
38:  * The {@link #tmpDir()}, {@link #dir(File)}, {@link #tmpJar()} and {@link #jar(File)} methods create instances,
39:  * controlling what file system space will be used.
40:  * <p>
41:  * The {@link #write(String, String)}, {@link #mkdir(String)} and {@link #path(String)} methods can be used for creating and getting at content.
42:  * <p>
43:  * The {@link #getRoot()} method provides a path object for the root of the base dir.
44:  * <p>
45:  * This type implements {@link Closeable}.
46:  * Closing an embedded base dir causes the base dir to be <b>removed</b> from the real file system.
47:  * It is generally always desirable to close the base dir in order not to leave files around.
48:  * The {@link #use(Action)} method allows an action to be executed before having the base dir be automatically closed.
49:  */
50: public interface EphemeralBaseDir extends AutoCloseable {
51: 
52:   /**
53:    * Creates a new base dir, using a newly created dir within the JVM's assigned temp dir.
54:    *
55:    * @return a new embedded base dir
56:    */
57:   static EmbeddedBaseDir tmpDir() {
58:     return dir(com.google.common.io.Files.createTempDir());
59:   }
60: 
61:   /**
62:    * Creates a new base dir, using the given dir as the root.
63:    * <p>
64:    * <b>Note:</b> if the returned base dir is closed, the given dir will be deleted.
65:    *
66:    * @param dir the base dir root
67:    * @return a new embedded base dir
68:    */
69:   static EmbeddedBaseDir dir(File dir) {
70:     return new PathEmbeddedBaseDir(dir);
71:   }
72: 
73:   /**
74:    * Creates a new base dir which is actually a jar created within the JVM's assigned temp dir.
75:    * <p>
76:    * This is typically used when testing Ratpack extensions to verify that they don't assume they are
77:    * running from the default file system.
78:    *
79:    * @return a new embedded base dir
80:    */
81:   static EmbeddedBaseDir tmpJar() {
82:     return jar(Exceptions.uncheck(() -> File.createTempFile("ratpack", ".jar")));
83:   }
84: 
85:   /**
86:    * Creates a new base dir which is actually a jar at the given location.
87:    * <p>
88:    * This is typically used when testing Ratpack extensions to verify that they don't assume they are
89:    * running from the default file system.
90:    * <p>
91:    * The given file is expected to exist and be empty.
92:    *
93:    * @param jarFile the location of the jar to act as a base dir
94:    * @return a new embedded base dir
95:    */
96:   static EmbeddedBaseDir jar(File jarFile) {
97:     return new JarFileEmbeddedBaseDir(jarFile);
98:   }
99: 
100:   /**
101:    * Add's a JVM shutdown hook that will {@link #close()} this base dir.
102:    *
103:    * @return {@code this}
104:    */
105:   default EmbeddedBaseDir closeOnExit() {
106:     Runtime.getRuntime().addShutdownHook(new Thread() {
107:       @Override
108:       public void run() {
109:         try {
110:           close();
111:         } catch (IOException e) {
112:           throw Exceptions.uncheck(e);
113:         }
114:       }
115:     });
116:     return this;
117:   }
118: 
119:   /**
120:    * Executes the given action with this base dir, then closes this base dir.
121:    *
122:    * @param action the action to execute before closing this base dir
123:    * @throws Exception any thrown by {@code action}
124:    */
125:   default void use(Action<? super EmbeddedBaseDir> action) throws Exception {
126:     try {
127:       action.execute(this);
128:     } finally {
129:       close();
130:     }
131:   }
132: 
133:   /**
134:    * Returns a path for the given path within the base dir.
135:    * <p>
136:    * All parent directories will be created on demand.
137:    *
138:    * @param path the relative path to the path
139:    * @return a path for the given path
140:    */
141:   default Path path(String path) {
142:     Path pathObj = getRoot().resolve(path);
143:     Exceptions.uncheck(() -> Files.createDirectories(pathObj.getParent()));
144:     return pathObj;
145:   }
