38:   private final ByteBuf byteBuf;
39:   private final LoadingCache<TemplateSource, CompiledTemplate> compiledTemplateCache;
40:   private final TemplateSource templateSource;
41:   private final Map<String, ?> model;
42:   private final Function<String, TemplateSource> includeTransformer;
43: 
44:   public Render(ExecContext execControl, ByteBuf byteBuf, LoadingCache<TemplateSource, CompiledTemplate> compiledTemplateCache, TemplateSource templateSource, final Map<String, ?> model, Function<String, TemplateSource> includeTransformer) {
45:     this.execControl = execControl;
46:     this.byteBuf = byteBuf;
47:     this.compiledTemplateCache = compiledTemplateCache;
48:     this.templateSource = templateSource;
49:     this.model = model;
50:     this.includeTransformer = includeTransformer;
51:   }
