53:   private Promise<ByteBuf> invoke() {
54:     return execControl.promise(new Action<Fulfiller<ByteBuf>>() {
55:       @Override
56:       public void execute(Fulfiller<ByteBuf> fulfiller) throws Exception {
57:         try {
58:           CompiledTemplate fromCache = getFromCache(compiledTemplateCache, templateSource);
59:           Render.this.execute(fromCache, model, byteBuf);
60:           fulfiller.success(byteBuf);
61:         } catch (Throwable e) {
62:           fulfiller.error(e);
63:         }
64:       }
65:     });
66:   }
67: 
68:   private CompiledTemplate getFromCache(LoadingCache<TemplateSource, CompiledTemplate> compiledTemplateCache, TemplateSource templateSource) {
69:     try {
70:       return compiledTemplateCache.get(templateSource);
71:     } catch (ExecutionException | UncheckedExecutionException e) {
72:       throw uncheck(toException(e.getCause()));
73:     }
74:   }
75: 
76:   private void executeNested(final String templatePath, final Map<String, ?> model, ByteBuf buffer) throws Exception {
77:     TemplateSource templateSource = includeTransformer.apply(templatePath);
78:     CompiledTemplate compiledTemplate = getFromCache(compiledTemplateCache, templateSource);
79:     execute(compiledTemplate, model, buffer);
80:   }
81: 
82:   private void execute(CompiledTemplate compiledTemplate, final Map<String, ?> model, final ByteBuf parts) throws Exception {
83:     compiledTemplate.execute(model, parts, new NestedRenderer() {
84:       public void render(String templatePath, Map<String, ?> nestedModel) throws Exception {
85:         Map<String, Object> modelCopy = new HashMap<>(model);
86:         modelCopy.putAll(nestedModel);
87:         executeNested(templatePath, modelCopy, parts);
88:       }
89:     });
90:   }
