92:   public static Promise<ByteBuf> render(ExecContext execContext, ByteBuf byteBuf, LoadingCache<TemplateSource, CompiledTemplate> compiledTemplateCache, TemplateSource templateSource, Map<String, ?> model, Function<String, TemplateSource> includeTransformer) throws Exception {
93:     return new Render(execContext, byteBuf, compiledTemplateCache, templateSource, model, includeTransformer).invoke();
