392:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
393:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
394:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
395:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
396: 
397:     LOGGER.error(msg);
398: 
399:     Response response = requestConstants.response.status(500);
400:     if (getServerConfig().isDevelopment()) {
401:       response.send(msg);
402:     } else {
403:       response.send();
404:     }
405:   }
