114:   private static class ChainIndex implements Iterator<Handler> {
115:     final Handler[] handlers;
116:     Registry registry;
117:     final boolean isFirstChain;
118:     int currentIndex;
119: 
120:     private ChainIndex(Handler[] handlers, Registry registry, boolean isFirstChainParam) {
121:       this.handlers = handlers;
122:       this.registry = registry;
123:       this.isFirstChain = isFirstChainParam;
124:     }
125: 
126:     public Handler next() {
127:       return handlers[currentIndex++];
128:     }
