218:   public void next() {
219:     Handler currentHandler = null;
220: 
221:     ChainIndex index = requestConstants.indexes.peek();
222:     while (currentHandler == null) {
223:       if (index.hasNext()) {
224:         currentHandler = index.next();
225:         if (currentHandler.getClass().equals(ChainHandler.class)) {
226:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) currentHandler).getHandlers(), getRegistry(), false));
227:           index = requestConstants.indexes.peek();
228:           currentHandler = null;
229:         }
230:       } else if (index.isFirstChain) {
231:         currentHandler = requestConstants.applicationConstants.end;
232:       } else {
233:         requestConstants.indexes.pop();
234:         index = requestConstants.indexes.peek();
235:       }
236:     }
237: 
238:     try {
239:       requestConstants.handler = currentHandler;
240:       currentHandler.handle(this);
241:     } catch (Throwable e) {
242:       if (e instanceof HandlerException) {
243:         throw (HandlerException) e;
244:       } else {
245:         throw new HandlerException(e);
246:       }
247:     }
248:   }
