286:       return DefaultExecController.this;
287:     }
288: 
289: 
290:     public void join(final Action<? super ratpack.exec.Execution> action) {
291:       segments.addFirst(new UserCodeSegment(action));
292:       waiting = false;
293:       tryDrain();
294:     }
295: 
