30: /**
31:  * An extension module that provides support for Thymeleaf templating engine.
32:  * <p>
33:  * To use it one has to register the module and then render {@link ratpack.thymeleaf.Template} instances.
34:  * Instances of {@code Template} can be created using one of the
35:  * {@link ratpack.thymeleaf.Template#thymeleafTemplate(java.util.Map, String, String)}
36:  * static methods.
37:  * </p>
38:  * <p>
39:  * By default templates are looked up in the {@code thymeleaf} directory of the application root with a {@code .html} suffix.
40:  * So {@code thymeleafTemplate("my/template/path")} maps to {@code thymeleaf/my/template/path.html} in the application root directory.
41:  * This can be configured using {@link #setTemplatesPrefix(String)} and {@link #setTemplatesSuffix(String)} as well as
42:  * {@code other.thymeleaf.templatesPrefix} and {@code other.thymeleaf.templatesSuffix} configuration properties.
43:  * </p>
44:  * <p>
45:  * Response content type can be manually specified, i.e. {@code thymeleafTemplate("template", model, "text/html")} if
46:  * not specified will default to {@code text/html}.
47:  * </p>
48:  *
49:  * Example usage: (Java DSL)
50:  * <pre class="tested">
51:  * import ratpack.handling.*;
52:  * import ratpack.guice.*;
53:  * import ratpack.util.*;
54:  * import ratpack.launch.*;
55:  * import ratpack.thymeleaf.ThymeleafModule;
56:  * import static ratpack.thymeleaf.Template.thymeleafTemplate;
57:  *
58:  * class MyHandler implements Handler {
59:  *   void handle(final Context context) {
60:  *     context.render(thymeleafTemplate("my/template/path", key: "it works!"));
61:  *   }
62:  * }
63:  *
64:  * class ModuleBootstrap implements Action&lt;ModuleRegistry&gt; {
65:  *   public void execute(ModuleRegistry modules) {
66:  *     modules.register(new ThymeleafModule());
67:  *   }
68:  * }
69:  *
70:  * LaunchConfig launchConfig = LaunchConfigBuilder.baseDir(new File("appRoot"))
71:  *     .build(new HandlerFactory() {
72:  *   public Handler create(LaunchConfig launchConfig) {
73:  *     return Guice.handler(launchConfig, new ModuleBootstrap(), new Action&lt;Chain&gt;() {
74:  *       public void execute(Chain chain) {
75:  *         chain.handler(chain.getRegistry().get(MyHandler.class));
76:  *       }
77:  *     });
78:  *   }
79:  * });
80:  * </pre>
81:  *
82:  * Example usage: (Groovy DSL)
83:  * <pre class="groovy-ratpack-dsl">
84:  * import ratpack.thymeleaf.ThymeleafModule
85:  * import static ratpack.thymeleaf.Template.thymeleafTemplate
86:  *
87:  * ratpack {
