402:      * If time between last access and current time is less than or equal to max inactive time, session will become valid.
403:      *
404:      * @return the maximum session inactivity time
405:      */
406:     public Duration getMaxInactivityInterval() {
407:       return maxInactivityInterval;
408:     }
409: 
410:     /**
411:      * Set maximum inactivity time (in seconds) of the cookie session.
412:      *
413:      * @param maxInactivityInterval a maximum inactivity time of the cookie session
414:      */
415:     public void setMaxInactivityInterval(Duration maxInactivityInterval) {
416:       this.maxInactivityInterval = maxInactivityInterval;
417:     }
418: 
419:     /**
420:      * The service used to serialize/deserialize the cookie session entries.
421:      * Defaults to {@link ratpack.session.clientside.internal.DefaultClientSessionService}
422:      *
423:      * @return the service used to serialize/deserialize the cookie session entries.
424:      */
425:     public SessionService getSessionService() {
426:       return sessionService;
427:     }
428: 
429:     /**
430:      * Set the service used to serialize/deserialize the cookie session entries.
431:      *
432:      * @param sessionService a service used to serialize/deserialize the cookie session entries.
433:      */
434:     public void setSessionService(SessionService sessionService) {
435:       this.sessionService = sessionService;
436:     }
437: 
438:     /**
439:      * The serializer of values of cookie session entries.
440:      * <p>
441:      * If not defined <b>default</b> {@link ratpack.session.clientside.serializer.StringValueSerializer} is used.
442:      *
443:      * @return the serializer of values of cookie session entries.
444:      */
445:     public ValueSerializer getValueSerializer() {
446:       return valueSerializer;
447:     }
448: 
449:     /**
450:      * Set a serializer of values of cookie session entries
451:      *
452:      * @param valueSerializer a serializer of values of cookie session entries
453:      */
454:     public void setValueSerializer(ValueSerializer valueSerializer) {
455:       this.valueSerializer = valueSerializer;
456:     }
457:   }
