163:    *
164:    * @return this
165:    * @throws Exception if the spec errors when being applied.
166:    */
167:   public abstract RatpackLauncher registry(Action<? super RegistrySpec> action) throws Exception;
168: 
169:   private static class DefaultRatpackLauncher extends RatpackLauncher {
170: 
171:     private ServerConfig serverConfig;
172:     private Registry userRegistry;
173: 
174:     DefaultRatpackLauncher(ServerConfig serverConfig) {
175:       this.serverConfig = serverConfig;
176:       this.userRegistry = Registries.empty();
177:     }
178: 
179:     @Override
180:     public RatpackServer build(HandlerFactory factory) {
181:       try {
182:         Registry baseRegistry = baseRegistry(serverConfig, userRegistry);
183:         return RatpackServerBuilder.build(baseRegistry, factory);
184:       } catch (Exception e) {
185:         throw uncheck(e);
186:       }
187:     }
188: 
189:     @Override
190:     public RatpackLauncher registry(Action<? super RegistrySpec> action) throws Exception {
191:       userRegistry = Registries.registry(action);
192:       return this;
193:     }
194: 
195:   }
196: 
197: }
