32: /**
33:  * Handler that runs and renders health checks executing in non-blocking mode
34:  * <p>
35:  * This handler queries {@code context} for either all {@link ratpack.health.HealthCheck}s or health check with the given name.
36:  * Then handler gets {@link ratpack.exec.Promise} returning {@link ratpack.health.HealthCheck.Result} for every health check to execute.
37:  * {@code concurrencyLevel} determines if promises are executed:
38:  * <ul>
39:  *   <li>in parallel (if {@code concurrencyLevel=0})</li>
40:  *   <li>in sequence (if {@code concurrencyLevel=1})</li>
41:  *   <li>in groups (if {@code concurrencyLevel >= 2}). Groups are executed in sequence while promises inside group in parallel</li>
42:  * </ul>
43:  * IMPORTANT: the real concurrency level depends on the event loop size. Event loop sets the higher limit of concurrency.
44:  * If event loop size is 8 ({@link ratpack.exec.internal.DefaultExecController#DefaultExecController}), the 9th health check will wait for the first.
45: 
46:  * <p>
47:  * This handler should be bound to an application path, and most likely only for the GET method.
48:  * <p>
49:  * The handler can render the result of all of the health checks or an individual health check, depending on the presence of a path token.
50:  * The path token provides the name of the health check to render.
51:  * If the path token is not present, all health checks will be rendered.
52:  * The token name to use can be provided as the construction argument to this handler.
53:  * <p>
54:  * If the token is present, the health check whose name is the value of the token will be rendered.
55:  * If no health check exists by that name, the client will receive a {@code HTTP 404}.
56:  * <p>
57:  * When a single health check is selected (by presence of the path token)
58:  * the {@link ratpack.health.HealthCheckResults} with one {@link ratpack.health.HealthCheck.Result}
59:  * is {@link Context#render(Object) rendered}.
60:  * When rendering all health checks a {@link ratpack.health.HealthCheckResults} is {@link Context#render(Object) rendered}.
61:  * <p>
62:  * The default {@link ratpack.health.HealthCheckResultsRenderer} is added to base registry. It renders in plain text.
63:  * If you wish to change the output, to JSON for example, you can register your own renderer for {@link ratpack.health.HealthCheckResults}.
64:  * See example in test cases {@code HealthCheckHandlerSpec}.
65:  * <pre class="java">{@code
66:  * import ratpack.exec.ExecControl;
67:  * import ratpack.exec.Promise;
68:  * import ratpack.guice.Guice;
69:  * import ratpack.health.HealthCheck;
70:  * import ratpack.health.HealthCheckHandler;
71:  * import ratpack.health.HealthCheckResultsRenderer;
72:  * import ratpack.test.embed.EmbeddedApp;
73:  *
74:  * import static org.junit.Assert.*;
75:  *
76:  * public class Example {
77:  *   public static class FooHealthCheck implements HealthCheck {
78:  *     public String getName() { return "foo"; }
79:  *     public Promise<HealthCheck.Result> check(ExecControl execControl) throws Exception {
80:  *       return execControl.promise(f -> {
81:  *         f.success(HealthCheck.Result.healthy());
82:  *       });
83:  *     }
84:  *   }
85:  *
86:  *   public static void main(String... args) throws Exception {
87:  *     EmbeddedApp.of(s -> s
88:  *       .registry(Guice.registry(b -> b
89:  *         .bind(FooHealthCheck.class)
90:  *         .bindInstance(HealthCheck.class, HealthCheck.of("bar", execControl -> {
91:  *           return execControl.promise(f -> {
92:  *             f.success(HealthCheck.Result.unhealthy("FAILED"));
93:  *           });
94:  *         }))
95:  *         .bindInstance(HealthCheckHandler.class, new HealthCheckHandler("bar"))
96:  *       ))
97:  *       .handler(r -> new HealthCheckHandler())
98:  *       ).test(httpClient -> {
99:  *         String result = httpClient.getText();
100:  *         assertNotNull(result);
101:  *         assertTrue(!"".equals(result));
102:  *         String[] results = result.split("\n");
103:  *         assertEquals(results.length, 2);
104:  *         assertEquals("bar : UNHEALTHY [FAILED]", results[0]);
105:  *         assertEquals("foo : HEALTHY", results[1]);
106:  *       });
107:  *   }
108:  * }
109:  * }</pre>
110:  *
111:  * @see ratpack.health.HealthCheck
112:  * @see ratpack.health.HealthCheckResults
113:  * @see ratpack.health.HealthCheckResultsRenderer
114:  */
115: public class HealthCheckHandler implements Handler {
116:   /**
117:    * Default concurrency level is 0 - potentially infinite parallelism in health checks execution
118:    */
119:   public static final int DEFAULT_CONCURRENCY_LEVEL = 0;
120: 
121:   private final String name;
122:   private final int concurrencyLevel;
123: 
124:   /**
125:    * Default constructor with {@code concurrencyLevel} set to 0 (infinite potential parallelism) and
126:    * undefined health check name.
127:    */
128:   public HealthCheckHandler() {
129:     this(null, DEFAULT_CONCURRENCY_LEVEL);
130:   }
131: 
132:   /**
133:    * Health check of the given name will be executed. If not registered HTTP 404 error is reported.
134:    * @param pathTokenName health check name
135:    */
136:   public HealthCheckHandler(String pathTokenName) {
137:     this(pathTokenName, DEFAULT_CONCURRENCY_LEVEL);
138:   }
139: 
140:   /**
141:    * Execute all registered health check with the given {@code concurrencyLevel}.
142:    * @param concurrencyLevel the level of parallelism for health check promises execution. Define number of health checks (as promises) to be run in parallel.
143:    * <ul>
144:    *   <li><strong>0</strong> - infinite potential parallelism - up to the event loop number of threads</li>
145:    *   <li><strong>1</strong> - serial, promises run one by one in sequence</li>
146:    *   <li><strong>2</strong> - max 2 at a time promises run in parallel</li>
147:    *   <li><strong>3</strong> - max 3 at a time promises run in parallel</li>
148:    *   <li><strong>n</strong> - max n at a time promises run in parallel</li>
149:    * </ul>
150:    */
151:   public HealthCheckHandler(int concurrencyLevel) {
152:     this(null, concurrencyLevel);
153:   }
154: 
155:   /**
156:    * Execute health check of the given name and given {@code concurrencyLevel}.
157:    *
158:    * @param healthCheckName the name of health check
159:    * @param concurrencyLevel the level of parallelism for health check promises execution. Define number of health checks (as promises) to be run in parallel.
160:    * <ul>
161:    *   <li><strong>0</strong> - infinite potential parallelism - up to the event loop number of threads</li>
162:    *   <li><strong>1</strong> - serial, promises run one by one in sequence</li>
163:    *   <li><strong>2</strong> - max 2 at a time promises run in parallel</li>
164:    *   <li><strong>3</strong> - max 3 at a time promises run in parallel</li>
165:    *   <li><strong>n</strong> - max n at a time promises run in parallel</li>
166:    * </ul>
167:    */
168:   protected HealthCheckHandler(String healthCheckName, int concurrencyLevel) {
169:     this.name = healthCheckName;
170:     this.concurrencyLevel = concurrencyLevel;
171:   }
172: 
173:   /**
174:    * Get the level of parallelism in non-blocking health check execution.
175:    *
176:    * @return concurrency level as defined in {@link ratpack.health.HealthCheckHandler#HealthCheckHandler} constructor. Parameter {@code concurrencyLevel}.
177:    */
178:   public int getConcurrencyLevel() {
179:     return concurrencyLevel;
180:   }
181: 
182:   /**
183:    * Get assigned health check name. If defined health check of this name is executed.
184:    *
185:    * @return health check name to be executed
186:    */
187:   public String getName() {
188:     return name;
189:   }
190: 
191:   /**
192:    * Run individual health check with the given name or all health checks.
193:    * The {@code concurrencyLevel} determines parallelism in health check execution.
194:    *
195:    * @param context request context and exec control as well
196:    * @throws Exception if anything goes wrong, exception will be implicitly passed to the context's {@link Context#error(Throwable)} method
197:    */
198:   @Override
199:   public void handle(Context context) throws Exception {
200:     if (name != null && !"".equals(name)) {
201:       handleByName(context, name);
202:     } else {
203:       handleAll(context);
204:     }
205:   }
206: 
207:   private void handleByName(Context context, String name) throws Exception {
208:     if (name == null || "".equals(name)) {
209:       context.clientError(404);
210:       return;
211:     }
212:     Optional<HealthCheck> hcheck = context.first(TypeToken.of(HealthCheck.class), hc -> {
213:       if (hc.getName().equals(name)) {
214:         return hc;
215:       } else {
216:         return null;
217:       }
218:     });
219:     if (!hcheck.isPresent()) {
220:       context.clientError(404);
221:       return;
222:     }
223:     try {
224:       Promise<HealthCheck.Result> promise = hcheck.get().check(context.getExecution().getControl());
225:       promise.onError(throwable -> {
226:         context.render(new HealthCheckResults(ImmutableSortedMap.<String, HealthCheck.Result>of(hcheck.get().getName(), HealthCheck.Result.unhealthy(throwable))));
227:       }).then(r -> {
228:         context.render(new HealthCheckResults(ImmutableSortedMap.<String, HealthCheck.Result>of(hcheck.get().getName(), r)));
229:       });
230:     } catch (Exception ex) {
231:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, HealthCheck.Result>of(hcheck.get().getName(), HealthCheck.Result.unhealthy(ex))));
232:     }
233:   }
234: 
235:   private void handleAll(Context context) throws Exception {
236:     SortedMap<String, HealthCheck.Result> hcheckResults = new ConcurrentSkipListMap<>();
237: 
238:     SortedMap<String, Promise<HealthCheck.Result>> promises = new ConcurrentSkipListMap<>();
239:     context.getAll(HealthCheck.class).forEach(hcheck -> {
240:       try {
241:         Promise<HealthCheck.Result> promise = hcheck.check(context.getExecution().getControl());
242:         promises.put(hcheck.getName(), promise);
243:       } catch (Exception ex) {
244:         hcheckResults.put(hcheck.getName(), HealthCheck.Result.unhealthy(ex));
245:       }
246:     });
247: 
248:     if (promises.size() == 0) {
249:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, HealthCheck.Result>copyOfSorted(hcheckResults)));
250:       return;
251:     }
252: 
253:     context.promise(f -> {
254:       // execute promises in parallel based on the concurrencyLevel
255:       // count finished health checks. If all are done, render results
256:       AtomicInteger executedPromisesCountDown = new AtomicInteger(promises.size());
257:       // count health checks waiting for execution.
258:       AtomicInteger toExecPromisesCountDown = new AtomicInteger(promises.size());
259:       // collect health checks to execute in the next run. Used when concurrencyLevel > 1
260:       Map<String, Promise<HealthCheck.Result>> toExecPromises = new ConcurrentHashMap<>();
261: 
262:       promises.forEach((name, p) -> {
263:         boolean execParallel = false;
264:         if (concurrencyLevel <= 0) {
265:           // execute all health checks in parallel
266:           execParallel = true;
267:         } else if (concurrencyLevel == 1) {
268:           // execute promise by promise, in sequence
269:           execParallel = false;
270:         } else {
271:           // collect promises into group of concurrencyLevel size or into group of last promises to execute
272:           toExecPromises.put(name, p);
273:           if (toExecPromisesCountDown.decrementAndGet() > 0 && toExecPromises.size() < concurrencyLevel) {
274:             return;
275:           }
276:           // execute promises in group in parallel
277:           execParallel = true;
278:         }
279: 
280:         if (toExecPromises.size() > 0) {
281:           // promise of immutable map of promises to execute, controls construction and their parallel execution while allows
282:           // safe freeing of toExecPromises map.
283:           context.promiseOf(ImmutableMap.<String, Promise<HealthCheck.Result>>copyOf(toExecPromises)).then(map -> {
284:             // control finalization of parent promise
285:             AtomicInteger groupOfPromisesCountDown = new AtomicInteger(map.size());
286:             context.promise(f2 -> {
287:               map.forEach((name2, p2) -> {
288:                 // execute promise p2 and check end condition: either last promise in group or last promise globally
289:                 execPromiseWithEndCondition(context, name2, p2, f2, hcheckResults, groupOfPromisesCountDown, executedPromisesCountDown);
290:               });
291:             }).then(finish -> {
292:               if (finish == Boolean.TRUE) {
293:                 f.success(hcheckResults);
294:               }
295:             });
296:           });
297: 
298:           toExecPromises.clear();
299: 
300:         } else {
301:           if (execParallel) {
302:             // execute promise and if last promise globally, return health check results
303:             execPromiseWithEndResult(context, name, p, f, hcheckResults, executedPromisesCountDown);
304:           } else {
305:             context.promise(f2 -> {
306:               // execute promise p and check end condition: if last promise globally
307:               execPromiseWithEndCondition(context, name, p, f2, hcheckResults, null, executedPromisesCountDown);
308:             }).then(finish -> {
309:               if (finish == Boolean.TRUE) {
310:                 f.success(hcheckResults);
311:               }
312:             });
313:           }
314:         }
315:       });
316:     }).then(results -> {
317:       context.render(new HealthCheckResults(ImmutableSortedMap.<String, HealthCheck.Result>copyOfSorted(hcheckResults)));
318:     });
319:   }
320: 
321:   /**
322:    * Execute promise and if last ({@code executedPromisesCountDown} is 0) return sorted map of health check results.
323:    * @param context execution context
324:    * @param name health check name
325:    * @param promise health check promise with calculation to be run
326:    * @param fulfiller fulfiller of an asynchronous promise
327:    * @param hcheckResults sorted map of health check results
328:    * @param executedPromisesCountDown counter of executed promises (counts down)
329:    */
330:   private void execPromiseWithEndResult(
331:           Context context,
332:           String name,
333:           Promise<HealthCheck.Result> promise,
334:           Fulfiller<Object> fulfiller,
335:           SortedMap<String, HealthCheck.Result> hcheckResults,
336:           AtomicInteger executedPromisesCountDown) {
337: 
338:     context.exec().onComplete(execution -> {
339:       if (executedPromisesCountDown.decrementAndGet() == 0) {
340:         fulfiller.success(hcheckResults);
341:       }
342:     }).onError(throwable -> {
