29: public class WiretapPublisher<T> implements Publisher<T> {
30: 
31:   private final Publisher<T> publisher;
32:   private final Action<? super StreamEvent<? super T>> listener;
33:   private final AtomicInteger counter = new AtomicInteger();
34: 
35:   public WiretapPublisher(Publisher<T> publisher, Action<? super StreamEvent<? super T>> listener) {
36:     this.publisher = publisher;
37:     this.listener = listener;
38:   }
39: 
40:   @Override
41:   public void subscribe(final Subscriber<? super T> outSubscriber) {
42:     final int subscriptionId = counter.getAndIncrement();
43:     publisher.subscribe(new Subscriber<T>() {
44: 
45:       private Subscription subscription;
46:       private final AtomicBoolean done = new AtomicBoolean();
47: 
48:       @Override
49:       public void onSubscribe(final Subscription subscription) {
50:         this.subscription = subscription;
51:         outSubscriber.onSubscribe(new Subscription() {
52:           @Override
53:           public void request(long n) {
54:             try {
55:               listener.execute(new RequestEvent<>(subscriptionId, n));
56:             } catch (Throwable throwable) {
57:               subscription.cancel();
58:               onError(throwable);
59:               return;
60:             }
61:             subscription.request(n);
62:           }
63: 
64:           @Override
65:           public void cancel() {
66:             try {
67:               listener.execute(new CancelEvent<>(subscriptionId));
68:             } catch (Throwable throwable) {
69:               try {
70:                 subscription.cancel();
71:               } catch (Throwable e) {
72:                 throwable.addSuppressed(e);
73:               }
74:               onError(throwable);
75:               return;
76:             }
77:             subscription.cancel();
78:           }
79:         });
80:       }
81: 
82:       @Override
83:       public void onNext(T in) {
84:         try {
85:           listener.execute(new DataEvent<>(subscriptionId, in));
86:         } catch (Throwable throwable) {
87:           subscription.cancel();
88:           onError(throwable);
89:           return;
90:         }
91: 
92:         if (!done.get()) {
93:           outSubscriber.onNext(in);
94:         }
95:       }
96: 
97:       @Override
98:       public void onError(Throwable t) {
99:         if (done.compareAndSet(false, true)) {
100:           try {
101:             listener.execute(new ErrorEvent<>(subscriptionId, t));
102:           } catch (Throwable throwable) {
103:             t.addSuppressed(throwable);
104:             onError(t);
105:             return;
106:           }
107:           outSubscriber.onError(t);
108:         }
109:       }
110: 
