49:  * That said, Ratpack is designed to support something like Guice as an integral piece via it's {@link Registry} abstraction.
50:  * Guice is the “official” solution.
51:  * </p>
52:  * <h3>Starting a Guice Ratpack app</h3>
53:  * <p>
54:  * The user entry point for Ratpack applications is the {@link ratpack.launch.HandlerFactory} implementation
55:  * that is given to the {@link ratpack.launch.LaunchConfigBuilder#build(ratpack.launch.HandlerFactory)} method.
56:  * This implementation can use one of the {@code handler(...) } static methods.
57:  * <p>
58:  * Below is a complete example for bootstrapping a Guice based Ratpack application.
59:  * </p>
60:  * <pre class="tested">
61:  * import ratpack.handling.*;
62:  * import ratpack.registry.*;
63:  * import ratpack.guice.*;
64:  * import ratpack.launch.*;
65:  * import ratpack.func.*;
66:  * import com.google.inject.*;
67:  * import javax.inject.*;
68:  *
69:  * // Some service to be dependency injected
70:  * class SomeService {}
71:  *
72:  * // A Guice module that provides the service
73:  * class ServiceModule extends AbstractModule {
74:  *   protected void configure() {
75:  *     bind(SomeService.class);
76:  *   }
77:  * }
78:  *
79:  * // An action that registers the module with the registry, making it part of the application
80:  * class Bindings implements Action&lt;BindingsSpec&gt; {
81:  *   public void execute(BindingsSpec bindings) {
82:  *     bindings.add(new ServiceModule());
83:  *   }
84:  * }
85:  *
86:  * // A handler implementation that is dependency injected
87:  * {@literal @}Singleton
88:  * class InjectedHandler implements Handler {
89:  *   private final SomeService service;
90:  *
91:  *   {@literal @}Inject
92:  *   public InjectedHandler(SomeService service) {
93:  *     this.service = service;
94:  *   }
95:  *
96:  *   public void handle(Context exchange) {
97:  *     // …
98:  *   }
99:  * }
100:  *
101:  * // A chain configurer that adds a dependency injected handler to the chain
102:  * class HandlersBootstrap implements Action&lt;Chain&gt; {
103:  *   public void execute(Chain chain) {
104:  *
105:  *     // The registry in a Guice backed chain can be used to retrieve objects that were bound,
106:  *     // or to create objects that are bound “just-in-time”.
107:  *     Registry&lt;Object&gt; registry = chain.getRegistry();
108:  *     Handler injectedHandler = registry.get(InjectedHandler.class);
109:  *
110:  *     // Add the handler into the chain
111:  *     chain.get("some/path", injectedHandler);
112:  *   }
113:  * }
