199:    */
200:   public static Handler handler(LaunchConfig launchConfig, Action<? super BindingsSpec> moduleConfigurer, Function<? super Injector, ? extends Handler> injectorTransformer) throws Exception {
201:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, newInjectorFactory(launchConfig), injectorTransformer);
202:   }
203: 
204:   /**
205:    * Creates a handler that can be used as the entry point for a Guice backed Ratpack app.
206:    * <p>
207:    * Similar to {@link #chain(ratpack.launch.LaunchConfig, ratpack.func.Action, ratpack.func.Action)},
208:    * but provides the opportunity to use a <i>parent</i> injector when creating the injector to use for the application.
209:    * See Guice documentation for the semantics of parent/child injectors.
210:    * <p>
211:    * Typically only required when making a Ratpack application a component of a larger application.
212:    *
213:    * @param launchConfig The launch config of the server
214:    * @param parentInjector The injector to use as a parent of the injector to be created
215:    * @param moduleConfigurer The configurer of the {@link BindingsSpec} to back the created handler
216:    * @param chainConfigurer The configurer that builds the handler chain
217:    * @return A handler that makes all Guice bound objects available to the handlers added to the {@link Chain} given to {@code chainConfigurer}.
218:    */
219:   public static Handler handler(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, final Action<? super Chain> chainConfigurer) throws Exception {
220:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), new InjectorHandlerTransformer(launchConfig, chainConfigurer));
221:   }
222: 
223:   /**
224:    * Creates a handler that can be used as the entry point for a Guice backed Ratpack app.
225:    * <p>
226:    * This is a lower level version of {@link #handler(ratpack.launch.LaunchConfig, com.google.inject.Injector, ratpack.func.Action, ratpack.func.Action)}
227:    * that supports a custom final {@link Handler} creation strategy.
228:    *
229:    * @param launchConfig The launch config of the server
230:    * @param parentInjector The injector to use as a parent of the injector to be created
231:    * @param moduleConfigurer The configurer of the {@link BindingsSpec} to back the created handler
232:    * @param injectorTransformer Takes the final {@link Injector} instance that was created from the modules and returns the {@link Handler} to use
233:    * @return A handler that makes all Guice bound objects available to the handlers added to the {@link Chain} given to {@code chainConfigurer}.
234:    */
235:   public static Handler handler(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, Function<? super Injector, ? extends Handler> injectorTransformer) throws Exception {
236:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), injectorTransformer);
237:   }
238: 
239:   /**
240:    * Creates a Ratpack {@link Registry} backed by the given {@link Injector} that will create objects via “just-in-time” binding.
241:    * <p>
242:    * The returned registry differs from the registry returned by {@link #registry(com.google.inject.Injector)} in that it may return objects that were not explicitly bound,
243:    * via Guice's “just-in-time” binding mechanism.
244:    * This only applies to the {@link Registry#get(Class)} and {@link Registry#maybeGet(Class)} (for all overloads).
245:    * All other methods do not perform any just in time bindings.
246:    *
247:    * @param injector The injector to back the registry
248:    * @return A registry that wraps the injector
249:    */
250:   public static Registry justInTimeRegistry(Injector injector) {
251:     return new JustInTimeInjectorRegistry(injector);
252:   }
253: 
254:   /**
255:    * Creates a Ratpack {@link Registry} backed by the given {@link Injector} that will <b>NOT</b> create objects via “just-in-time” binding.
256:    *
257:    * @param injector The injector to back the registry
258:    * @return A registry that wraps the injector
259:    */
260:   public static Registry registry(Injector injector) {
261:     return Registries.registry(registryBacking(injector));
262:   }
263: 
264:   public static RegistryBacking registryBacking(final Injector injector) {
265:     return new InjectorRegistryBacking(injector);
266:   }
267: 
268:   /**
269:    * Creates a transformer that can build an injector from a module.
270:    * <p>
271:    * The module given to the {@code transform()} method may be {@code null}.
272:    *
273:    * @param launchConfig The launch config of the server
274:    * @return a transformer that can build an injector from a module
275:    */
276:   public static Function<Module, Injector> newInjectorFactory(final LaunchConfig launchConfig) {
277:     final Stage stage = launchConfig.isDevelopment() ? Stage.DEVELOPMENT : Stage.PRODUCTION;
278:     return new Function<Module, Injector>() {
279:       @Override
280:       public Injector apply(Module from) {
281:         return from == null ? createInjector(stage) : createInjector(stage, from);
282:       }
283:     };
284:   }
285: 
286:   /**
287:    * Creates a transformer that can build an injector from a module, as a child of the given parent.
288:    * <p>
289:    * The module given to the {@code transform()} method may be {@code null}.
290:    *
291:    * @param parent The parent injector
292:    * @return a transformer that can build an injector from a module, as a child of the given parent.
293:    */
294:   public static Function<Module, Injector> childInjectorFactory(final Injector parent) {
295:     return new Function<Module, Injector>() {
296:       @Override
297:       public Injector apply(Module from) {
298:         return from == null ? parent.createChildInjector() : parent.createChildInjector(from);
299:       }
300:     };
301:   }
302: 
303:   private static class InjectorHandlerTransformer implements Function<Injector, Handler> {
304:     private final LaunchConfig launchConfig;
305:     private final Action<? super Chain> action;
306: 
307:     public InjectorHandlerTransformer(LaunchConfig launchConfig, Action<? super Chain> action) {
308:       this.launchConfig = launchConfig;
309:       this.action = action;
310:     }
311: 
312:     public Handler apply(Injector injector) throws Exception {
313:       return chain(launchConfig, justInTimeRegistry(injector), action);
314:     }
315:   }
316: 
317:   private static class InjectorRegistryBacking implements RegistryBacking {
318:     private final Injector injector;
319: 
320:     public InjectorRegistryBacking(Injector injector) {
321:       this.injector = injector;
322:     }
323: 
324:     @Override
325:     public <T> Iterable<Supplier<? extends T>> provide(TypeToken<T> type) {
326:       return FluentIterable.from(GuiceUtil.allProvidersOfType(injector, type)).transform(new com.google.common.base.Function<Provider<? extends T>, Supplier<? extends T>>() {
327:         @Override
328:         public Supplier<? extends T> apply(final Provider<? extends T> provider) {
329:           return new Supplier<T>() {
330:             @Override
331:             public T get() {
332:               return provider.get();
333:             }
334:           };
335:         }
336:       });
337:     }
338: 
339:     @Override
340:     public boolean equals(Object o) {
341:       if (this == o) {
342:         return true;
343:       }
344:       if (o == null || getClass() != o.getClass()) {
345:         return false;
346:       }
347: 
348:       InjectorRegistryBacking that = (InjectorRegistryBacking) o;
349: 
350:       return injector.equals(that.injector);
351:     }
352: 
353:     @Override
354:     public int hashCode() {
355:       return injector.hashCode();
356:     }
357:   }
358: }
