93:    *     RxRatpack.initialize(); // must be called once for the life of the JVM
94:    *
95:    *     EmbeddedApp.fromHandlers(chain -> chain
96:    *       .register(s -> s
97:    *         .add(ServerErrorHandler.class, (ctx, throwable) ->
98:    *           ctx.render("caught by error handler: " + throwable.getMessage())
99:    *         )
100:    *       )
101:    *       .get(ctx -> Observable.<String>error(new Exception("!")).subscribe(ctx::render))
102:    *     ).test(httpClient ->
103:    *       assertEquals("caught by error handler: !", httpClient.getText())
104:    *     );
105:    *   }
106:    * }
107:    * }</pre>
108:    */
109:   @SuppressWarnings("unchecked")
110:   public static void initialize() {
111:     RxJavaPlugins.setErrorHandler(new ErrorHandler());
112:     RxJavaPlugins.setInitComputationSchedulerHandler(c -> DefaultSchedulers.getComputationScheduler());
113:     RxJavaPlugins.setInitIoSchedulerHandler(c -> DefaultSchedulers.getIoScheduler());
114:     RxJavaPlugins.setOnObservableSubscribe((observable, observer) -> new ExecutionBackedObserver<>(observer));
115:     RxJavaPlugins.setOnFlowableSubscribe((flowable, subscriber) -> new ExecutionBackedSubscriber<>(subscriber));
