150:   /**
151:    * Converts a {@link Promise} into an {@link Observable}.
152:    * <p>
153:    * The returned observable emits the promise's single value if it succeeds, and emits the error (i.e. via {@code onError()}) if it fails.
154:    * <p>
155:    * This method works well as a method reference to the {@link Promise#to(ratpack.func.Function)} method.
156:    * <pre class="java">{@code
157:    * import ratpack.rx2.RxRatpack;
158:    * import ratpack.exec.Promise;
159:    * import ratpack.test.exec.ExecHarness;
160:    *
161:    * import static org.junit.Assert.assertEquals;
162:    * import static org.junit.Assert.assertEquals;
163:    *
164:    * public class Example {
165:    *   public static String value;
166:    *   public static void main(String... args) throws Exception {
167:    *     ExecHarness.runSingle(e ->
168:    *       Promise.value("hello world")
169:    *         .to(RxRatpack::observe)
170:    *         .map(String::toUpperCase)
171:    *         .subscribe(s -> value = s)
172:    *     );
173:    *
174:    *     assertEquals("HELLO WORLD", value);
175:    *   }
176:    * }
177:    * }</pre>
178:    *
179:    * @param promise the promise
180:    * @param <T>     the type of value promised
181:    * @return an observable for the promised value
182:    */
183:   public static <T> Observable<T> observe(Promise<T> promise) {
184:     return Observable.create(subscriber ->
185:       promise.onError(subscriber::onError).then(value -> {
186:         subscriber.onNext(value);
187:         subscriber.onComplete();
188:       })
189:     );
190:   }
