118:   /**
119:    * Converts a {@link Operation} into an {@link Observable}.
120:    * <p>
121:    * The returned observable emits completes upon completion of the operation without emitting a value, and emits the error (i.e. via {@code onError()}) if it fails.
122:    * <pre class="java">{@code
123:    * import ratpack.rx2.RxRatpack;
124:    * import ratpack.exec.Operation;
125:    * import ratpack.test.exec.ExecHarness;
126:    *
127:    * import static org.junit.Assert.assertTrue;
128:    *
129:    * public class Example {
130:    *   public static boolean executed;
131:    *   public static void main(String... args) throws Exception {
132:    *     ExecHarness.runSingle(e ->
133:    *       Operation.of(() -> executed = true)
134:    *         .to(RxRatpack::observe)
135:    *         .subscribe()
136:    *     );
137:    *
138:    *     assertTrue(executed);
139:    *   }
140:    * }
141:    * }</pre>
142:    *
143:    * @param operation the operation
144:    * @return an observable for the operation
145:    */
146:   public static Observable<Void> observe(Operation operation) {
147:     return Observable.create(subscriber -> operation.onError(subscriber::onError).then(subscriber::onComplete));
148:   }
