322:   /**
323:    * Converts an {@link Observable} into a {@link Promise}, for all of the observable's items.
324:    * <p>
325:    * This method can be used to simply adapt an observable to a promise, but can also be used to bind an observable to the current execution.
326:    * It is sometimes more convenient to use {@link #promise(ObservableOnSubscribe)} over this method.
327:    * <p>
328:    * <pre class="java">{@code
329:    * import ratpack.rx2.RxRatpack;
330:    * import ratpack.test.exec.ExecHarness;
331:    * import io.reactivex.Observable;
332:    * import java.util.List;
333:    * import java.util.Arrays;
334:    * import static org.junit.Assert.assertEquals;
335:    *
336:    * public class Example {
337:    *   public static class AsyncService {
338:    *     public <T> Observable<T> observe(final T value) {
339:    *       return Observable.create(subscriber ->
340:    *         new Thread(() -> {
341:    *           subscriber.onNext(value);
342:    *           subscriber.onComplete();
343:    *         }).start()
344:    *       );
345:    *     }
346:    *   }
347:    *
348:    *   public static void main(String[] args) throws Throwable {
349:    *     List<String> results = ExecHarness.yieldSingle(execution ->
350:    *       RxRatpack.promise(new AsyncService().observe("foo"))
351:    *     ).getValue();
352:    *
353:    *     assertEquals(Arrays.asList("foo"), results);
354:    *   }
355:    * }
356:    * }</pre>
357:    * <p>
358:    * This method uses {@link Observable#toList()} to collect the observable's contents into a list.
359:    * It therefore should not be used with observables with many or infinite items.
360:    * <p>
361:    * If it is expected that the observable only emits one element, it is typically more convenient to use {@link #promiseSingle(Observable)}.
362:    * <p>
363:    * If the observable emits an error, the returned promise will fail with that error.
364:    * <p>
365:    * This method must be called during an execution.
366:    *
367:    * @param observable the observable
368:    * @param <T>        the type of the value observed
369:    * @return a promise that returns all values from the observable
370:    * @throws UnmanagedThreadException if called outside of an execution
371:    * @see #promiseSingle(Observable)
372:    */
373:   public static <T> Promise<List<T>> promise(Observable<T> observable) throws UnmanagedThreadException {
374:     return Promise.async(f -> observable.toList().subscribe(f::success, f::error));
375:   }
